#!/usr/bin/env python3

import math
import time
from dataclasses import replace

import rclpy
from rclpy.node import Node
from std_msgs.msg import Bool, Float32, Int8, Int32, String

from .course_mission import CourseMission, MissionInput


class CourseMissionNode(Node):
    """Final command arbiter for camera, GPS, Depth and Nav2 missions."""

    def __init__(self):
        super().__init__("course_mission_node")
        defaults = {
            "ramp_pitch_deg": 10.0, "ramp_delay_sec": 2.0,
            "stop_distance_m": 0.5, "minimum_stop_sec": 0.5,
            "command_rate_hz": 20.0,
            "sensor_timeout_sec": 0.5,
        }
        for name, value in defaults.items(): self.declare_parameter(name, value)
        self.logic = CourseMission(
            self.p("ramp_pitch_deg"), self.p("ramp_delay_sec"),
            self.p("stop_distance_m"), self.p("minimum_stop_sec"))
        self.data = MissionInput()
        self.updated = {}
        self.nav2_mission_section = None
        self.drive_pub = self.create_publisher(Int32, "/cmd_driving", 10)
        self.steer_pub = self.create_publisher(Float32, "/cmd_steer", 10)
        self.turn_pub = self.create_publisher(Int8, "/mission/turn_direction", 10)
        self.mode_pub = self.create_publisher(Int8, "/mission/control_mode", 10)
        self.status_pub = self.create_publisher(String, "/mission/status", 10)

        self.sub(Int8, "/mission/section", "section", int)
        self.sub(Int8, "/mission/gps_direction", "gps_direction", int)
        self.sub(Float32, "/imu/pitch_deg", "pitch_deg", float)
        self.sub(Bool, "/imu/valid", "imu_valid", bool)
        self.sub(Bool, "/perception/stop_detected", "stop_detected", bool)
        self.sub(Float32, "/perception/stop_line_distance_m", "stop_distance_m", float)
        self.sub(Bool, "/perception/stop_line_distance_valid", "stop_distance_valid", bool)
        self.sub(String, "/perception/traffic_light_state", "traffic_green", lambda x: str(x).strip().upper()=="GREEN")
        self.sub(Bool, "/perception/traffic20_detected", "traffic20_detected", bool)
        self.sub(Bool, "/camera/path_valid", "camera_path_valid", bool)
        self.sub(Float32, "/camera/target_steering_deg", "camera_steering_deg", float)
        self.sub(Bool, "/nav2/control_valid", "nav2_valid", bool)
        self.sub(Int8, "/nav2/target_speed_stage", "nav2_stage", int)
        self.sub(Float32, "/nav2/target_steering_deg", "nav2_steering_deg", float)
        self.sub(Float32, "/perception/yellow_line_distance_m", "yellow_distance_m", float)
        self.sub(Bool, "/perception/yellow_line_distance_valid", "yellow_distance_valid", bool)
        self.sub(Int8, "/perception/yellow_line_side", "yellow_side", int)
        self.create_subscription(String, "/mission/gps_mission", self.on_gps_mission, 10)
        self.create_subscription(Bool, "/nav2/mission_complete", self.on_nav2_complete, 10)
        self.create_timer(1.0/max(1.0,float(self.p("command_rate_hz"))), self.control)

    def p(self,name): return self.get_parameter(name).value
    def sub(self, msg_type, topic, field, convert):
        def callback(msg):
            value = convert(msg.data)
            if not isinstance(value, float) or math.isfinite(value):
                setattr(self.data, field, value)
                self.updated[field] = time.monotonic()
        self.create_subscription(msg_type, topic, callback, 10)

    def on_gps_mission(self, msg):
        mission = msg.data.strip().upper().replace("-", "_").replace(" ", "_")
        sections = {"T_COURSE": 7, "TCOURSE": 7,
                    "PARALLEL_PARKING": 10, "PARALLELPARKING": 10}
        section = sections.get(mission)
        if section is None:
            self.get_logger().warning(f"ignored unknown gps mission: {msg.data!r}")
            return
        self.nav2_mission_section = section
        self.data.section = section
        self.updated["section"] = time.monotonic()
        self.get_logger().info(f"GPS mission selected section {section}: {mission}")

    def on_nav2_complete(self, msg):
        if (not msg.data or self.nav2_mission_section not in (7, 10) or
                self.data.section != self.nav2_mission_section):
            return
        completed = self.nav2_mission_section
        self.data.section = 8 if completed == 7 else 11
        self.nav2_mission_section = None
        self.updated["section"] = time.monotonic()
        self.get_logger().info(
            f"Nav2 section {completed} completed; camera control resumes at section {self.data.section}")

    def control(self):
        now = time.monotonic(); self.data.now = now
        timeout = float(self.p("sensor_timeout_sec"))
        fresh = lambda *fields: all(now-self.updated.get(field, -1e9) <= timeout for field in fields)
        safe = replace(
            self.data,
            camera_path_valid=self.data.camera_path_valid and fresh("camera_path_valid", "camera_steering_deg"),
            imu_valid=self.data.imu_valid and fresh("imu_valid", "pitch_deg"),
            stop_detected=self.data.stop_detected and fresh("stop_detected"),
            stop_distance_valid=self.data.stop_distance_valid and fresh("stop_distance_valid", "stop_distance_m"),
            traffic_green=self.data.traffic_green and fresh("traffic_green"),
            traffic20_detected=self.data.traffic20_detected and fresh("traffic20_detected"),
            nav2_valid=self.data.nav2_valid and fresh("nav2_valid", "nav2_stage", "nav2_steering_deg"),
            yellow_distance_valid=(self.data.yellow_distance_valid and
                                   fresh("yellow_distance_valid", "yellow_distance_m", "yellow_side")),
        )
        output = self.logic.update(safe)
        self.drive_pub.publish(Int32(data=output.stage))
        self.steer_pub.publish(Float32(data=float(output.steering_deg)))
        self.turn_pub.publish(Int8(data=output.turn_direction))
        self.mode_pub.publish(Int8(data=output.control_mode))
        self.status_pub.publish(String(data=output.status))

    def destroy_node(self):
        if rclpy.ok():
            self.drive_pub.publish(Int32(data=0)); self.steer_pub.publish(Float32(data=0.0))
        return super().destroy_node()


def main(args=None):
    rclpy.init(args=args); node=CourseMissionNode()
    try: rclpy.spin(node)
    except KeyboardInterrupt: pass
    finally:
        node.destroy_node()
        if rclpy.ok(): rclpy.shutdown()


if __name__ == "__main__": main()
